  g.add(box(w, 0.07, 0.08, frame, 0, -h / 2, 0));
  g.add(box(0.07, h, 0.08, frame, -w / 2, 0, 0));
  g.add(box(0.07, h, 0.08, frame, w / 2, 0, 0));
  g.add(box(0.045, h, 0.05, frame, 0, 0, 0.01));
  g.add(box(w, 0.05, 0.05, frame, 0, 0, 0.01));
