export function buildEstate(family, env) {
  return createEstateBase(family, env);
}

export function updateEstate(anim, time, dt) {
  if (!anim) return;
  anim.people?.forEach((p, i) => {
    const phase = p.userData.phase;
    p.userData.person.position.y = Math.sin(time * 1.25 + phase) * 0.012;
    p.userData.person.rotation.z = Math.sin(time * 0.8 + phase) * 0.008;
    p.userData.arms.forEach(({ pivot, side, base }, ai) => {
      pivot.rotation.z = base + Math.sin(time * 1.05 + phase + ai) * 0.035;
      pivot.rotation.x = Math.sin(time * 0.7 + phase + ai * 2) * 0.02;
    });
    p.userData.ring.material.opacity = 0.28 + Math.sin(time * 1.8 + phase) * 0.09;
    p.userData.ring.scale.setScalar(1 + Math.sin(time * 1.4 + i) * 0.05);
  });
  anim.rings?.forEach((r) => {
    if (!r?.material) return;
  });
  anim.rotors?.forEach((rotor, i) => {
    if (i % 2 === 0) rotor.rotation.y += dt * 8.5;
    else rotor.rotation.z += dt * 14;
  });
  anim.sway?.forEach(({ object, phase, amp }) => {
    object.rotation.z = Math.sin(time * 0.7 + phase) * amp;
    object.rotation.x = Math.cos(time * 0.52 + phase) * amp * 0.6;
  });
  anim.ripples?.forEach(({ mesh, phase, max }) => {
    const t = ((time * 0.21 + phase) % 1);
    mesh.scale.setScalar(1 + t * max * 4.5);
    mesh.material.opacity = 0.23 * (1 - t);
  });
  if (anim.motes) {
    anim.motes.rotation.y = time * 0.018;
    anim.motes.position.y = Math.sin(time * 0.34) * 0.16;
  }
  anim.lights?.forEach(({ light, phase }) => {
    light.intensity = 2.2 + Math.sin(time * 8 + phase) * 0.45 + Math.sin(time * 13.7) * 0.2;
  });
}

export function disposeObject(obj) {
  obj.traverse((child) => {
    if (child.geometry) child.geometry.dispose();
    if (child.material) {
      const materials = Array.isArray(child.material) ? child.material : [child.material];
      materials.forEach((m) => {
        if (m.map) m.map.dispose();
        m.dispose();
      });
    }
  });
}

import * as THREE from 'three';
import { RoundedBoxGeometry } from 'three/addons/geometries/RoundedBoxGeometry.js';

const TAU = Math.PI * 2;

function std(color, roughness = 0.8, metalness = 0, extra = {}) {
  return new THREE.MeshStandardMaterial({ color, roughness, metalness, ...extra });
}

function rbox(w, h, d, r, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(new RoundedBoxGeometry(w, h, d, 3, r), mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

function box(w, h, d, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

function cyl(rt, rb, h, seg, mat, x = 0, y = 0, z = 0) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg), mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

function sph(r, mat, x = 0, y = 0, z = 0, detail = 14) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, detail, Math.max(6, Math.floor(detail / 2))), mat);
  m.position.set(x, y, z);
  m.castShadow = true;
  m.receiveShadow = true;
  return m;
}

function makeTextTexture(text, color = '#f4ead8', bg = 'rgba(0,0,0,0)', size = 700) {
  const c = document.createElement('canvas');
  c.width = 1024;
  c.height = 256;
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, c.width, c.height);
  if (bg !== 'rgba(0,0,0,0)') {
    ctx.fillStyle = bg;
    ctx.fillRect(0, 0, c.width, c.height);
  }
  ctx.fillStyle = color;
  ctx.font = `800 ${size}px Manrope, sans-serif`;
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(text, c.width / 2, c.height / 2);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 4;
  return tex;
}

function buildPlane(family) {
  const g = new THREE.Group();
  const accent = new THREE.Color(family.accent);
  const bodyMat = new THREE.MeshPhysicalMaterial({
    color: family.id === 'average' ? 0xf1f3f3 : 0xf6f1e8,
    roughness: 0.23,
    metalness: 0.38,
    clearcoat: 0.85,
  });
  const accentMat = new THREE.MeshPhysicalMaterial({
    color: accent,
    roughness: 0.28,
    metalness: 0.5,
    clearcoat: 0.5,
  });
  const dark = std(0x22272a, 0.4, 0.4);
  const glass = new THREE.MeshPhysicalMaterial({
    color: 0x253b46,
    metalness: 0.75,
    roughness: 0.02,
    transparent: true,
    opacity: 0.88,
  });
  // fuselage
  const fuse = new THREE.Mesh(new THREE.CylinderGeometry(0.72, 0.62, 12.5, 24), bodyMat);
  fuse.rotation.x = Math.PI / 2;
  fuse.castShadow = true;
  g.add(fuse);
  const nose = sph(0.72, bodyMat, 0, 0, 6.45, 20);
  nose.scale.set(1, 1, 1.55);
  g.add(nose);
  const tailCone = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.62, 2.0, 18), bodyMat);
  tailCone.rotation.x = Math.PI / 2;
  tailCone.position.set(0, 0.1, -7.0);
  g.add(tailCone);
  // stripe
  const stripe = new THREE.Mesh(new THREE.CylinderGeometry(0.725, 0.725, 0.22, 24, 1, true, -0.6, 1.2), accentMat);
  stripe.rotation.x = Math.PI / 2;
  stripe.position.z = 0.2;
  stripe.scale.z = 12.4;
  g.add(stripe);
  // windows
  for (let i = 0; i < 8; i++) {
    [-1, 1].forEach((side) => {
      const w = box(0.05, 0.2, 0.28, glass, side * 0.69, 0.25, -3.4 + i * 0.85);
      g.add(w);
    });
  }
  // cockpit
  const cockpit = sph(0.55, glass, 0, 0.3, 5.9, 16);
  cockpit.scale.set(1.1, 0.7, 1.1);
  g.add(cockpit);
  // wings
  const wingShape = new THREE.Shape();
  wingShape.moveTo(-0.9, 0);
  wingShape.lineTo(8.3, -1.15);
  wingShape.lineTo(8.5, 0.3);
  wingShape.lineTo(1.2, 1.5);
  wingShape.closePath();
  const wingGeo = new THREE.ExtrudeGeometry(wingShape, { depth: 0.12, bevelEnabled: false });
  [-1, 1].forEach((side) => {
    const wing = new THREE.Mesh(wingGeo, bodyMat);
    wing.rotation.x = -Math.PI / 2;
    wing.rotation.z = side < 0 ? Math.PI : 0;
    wing.position.set(0, -0.05, 0.4);
    wing.scale.x = side;
    wing.castShadow = true;
    g.add(wing);
    const tip = box(0.25, 0.22, 1.4, accentMat, side * 8.4, 0, 0.1);
    g.add(tip);
    const engine = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.4, 1.3, 16), bodyMat);
    engine.rotation.x = Math.PI / 2;
    engine.position.set(side * 3.4, -0.35, 1.7);
    engine.castShadow = true;
    g.add(engine);
    const intake = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.3, 0.06, 16), dark);
    intake.rotation.x = Math.PI / 2;
    intake.position.set(side * 3.4, -0.35, 2.37);
    g.add(intake);
  });
  // tail
  const finShape = new THREE.Shape();
  finShape.moveTo(0, 0);
  finShape.lineTo(0, 2.5);
  finShape.lineTo(2.0, 0.28);
  finShape.lineTo(2.0, 0);
  finShape.closePath();
  const finGeo = new THREE.ExtrudeGeometry(finShape, { depth: 0.14, bevelEnabled: false });
  const fin = new THREE.Mesh(finGeo, bodyMat);
  fin.position.set(0, 0.2, -7.0);
  fin.rotation.y = Math.PI / 2;
  fin.castShadow = true;
  g.add(fin);
  const finAccent = box(0.16, 1.9, 0.1, accentMat, 0, 1.45, -7.1);
  finAccent.rotation.z = -0.18;
  g.add(finAccent);
  const stab = box(5.3, 0.13, 1.0, bodyMat, 0, 0.1, -6.85);
  g.add(stab);
  // belly light
  const light = new THREE.PointLight(0xffe0ad, 1.0, 12, 2);
  light.position.set(0, -0.4, 4.2);
  g.add(light);
  g.userData = { light };
  return g;
}

function cloud(parent, x, y, z, scale, opacity = 0.42) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: 0xffefe2, transparent: true, opacity, depthWrite: false });
  const parts = [
    [0, 0, 0, 1],
    [1.05, 0.14, 0.1, 0.78],
    [-1.15, -0.08, 0.06, 0.68],
    [0.35, 0.37, -0.2, 0.72],
    [-0.45, 0.28, 0.18, 0.6],
  ];
  parts.forEach(([px, py, pz, s]) => {
    const blob = sph(1, mat, px, py, pz, 10);
    blob.scale.set(1.25 * s, 0.45 * s, 0.9 * s);
    blob.castShadow = false;
    g.add(blob);
  });
  g.position.set(x, y, z);
  g.scale.setScalar(scale);
  parent.add(g);
  return g;
}

export function buildFlightWorld(family, destination) {
  const root = new THREE.Group();
  root.name = 'flight-world';
  const clouds = new THREE.Group();
  root.add(clouds);
  const material = new THREE.MeshBasicMaterial({ color: 0xffe8d5, transparent: true, opacity: 0.5, depthWrite: false });
  for (let i = 0; i < 46; i++) {
    const x = (Math.random() - 0.5) * 75;
    const y = -5 + Math.random() * 7;
    const z = -55 + Math.random() * 75;
    const s = 2.7 + Math.random() * 6.5;
    const cl = cloud(clouds, x, y, z, s, 0.22 + Math.random() * 0.3);
    cl.rotation.y = Math.random() * TAU;
    cl.userData.speed = 0.4 + Math.random() * 0.8;
  }
  // low cloud sea
  const sea = new THREE.Mesh(
    new THREE.PlaneGeometry(250, 250, 1, 1),
    new THREE.MeshBasicMaterial({ color: 0xf5d9c6, transparent: true, opacity: 0.2, depthWrite: false })
  );
  sea.rotation.x = -Math.PI / 2;
  sea.position.y = -7;
  root.add(sea);

  const plane = buildPlane(family);
  plane.position.set(0, 2.8, 0);
  plane.rotation.y = 0.0;
  plane.rotation.z = 0.045;
  root.add(plane);

  return {
    root,
    kind: 'flight',
    destination,
    family,
    anim: {
      plane,
      clouds,
      time: 0,
      update(time, dt) {
        this.time += dt;
        plane.position.y = 2.8 + Math.sin(time * 0.9) * 0.12;
        plane.rotation.z = 0.045 + Math.sin(time * 0.7) * 0.025;
        clouds.children.forEach((cl) => {
          cl.position.z += dt * cl.userData.speed * 2.2;
          if (cl.position.z > 45) cl.position.z = -70;
        });
      },
    },
  };
}

