:root {
  --ink: #071013;
  --ink-soft: #0c181b;
  --ink-glass: rgba(9, 19, 22, 0.7);
  --ink-glass-heavy: rgba(8, 17, 20, 0.9);
  --cream: #f3ebdd;
  --cream-soft: #cfc8ba;
  --muted: #9fa8a3;
  --gold: #d8b274;
  --gold-bright: #f1d7a7;
  --gold-deep: #9d7841;
  --sage: #91a998;
  --line: rgba(243, 235, 221, 0.13);
  --line-strong: rgba(243, 235, 221, 0.24);
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.42);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
  --safe-left: env(safe-area-inset-left, 0px);
  --safe-right: env(safe-area-inset-right, 0px);
}

* {
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

html,
body {
  margin: 0;
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: var(--ink);
  color: var(--cream);
  font-family: 'Manrope', system-ui, -apple-system, sans-serif;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
  overscroll-behavior: none;
}

body {
  position: fixed;
  inset: 0;
}

button {
  font: inherit;
  color: inherit;
  border: 0;
  background: none;
  padding: 0;
  cursor: pointer;
  -webkit-tap-highlight-color: transparent;
}

button:focus-visible {
  outline: 2px solid var(--gold);
  outline-offset: 3px;
}

#app {
  position: relative;
  width: 100%;
  height: 100dvh;
  overflow: hidden;
  background: #0b1518;
}

#scene {
  display: block;
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  touch-action: none;
  cursor: grab;
}
#scene:active {
  cursor: grabbing;
}

.scene-vignette {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse at 55% 38%, transparent 20%, rgba(3, 9, 11, 0.18) 70%, rgba(3, 9, 11, 0.52) 100%),
    linear-gradient(180deg, rgba(3, 9, 11, 0.28) 0%, transparent 22%, transparent 70%, rgba(3, 9, 11, 0.64) 100%);
  z-index: 2;
}

.scene-warmth {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(118deg, rgba(216, 178, 116, 0.06), transparent 35%, rgba(22, 55, 66, 0.05));
  mix-blend-mode: screen;
  z-index: 2;
}

.grain {
  position: absolute;
  inset: -50%;
  pointer-events: none;
  opacity: 0.055;
  z-index: 3;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.8'/%3E%3C/svg%3E");
  animation: grainShift 0.7s steps(2) infinite;
}
@keyframes grainShift {
  0% { transform: translate(0, 0); }
  50% { transform: translate(1.5%, -1%); }
  100% { transform: translate(-1%, 1.5%); }
}

.hidden {
  display: none !important;
}

