.loader {
  position: fixed;
  inset: 0;
  z-index: 200;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 12px;
  background: radial-gradient(ellipse at center, #122227 0%, #071013 68%);
  transition: opacity 0.6s ease, visibility 0.6s;
}
.loader.ready {
  opacity: 0;
  visibility: hidden;
}
.loader-crest {
  width: 62px;
  height: 62px;
  border: 1px solid rgba(216, 178, 116, 0.5);
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--gold);
  font-family: 'Cormorant', serif;
  font-size: 30px;
  margin-bottom: 4px;
}
.loader-title {
  font-family: 'Manrope', sans-serif;
  font-weight: 700;
  letter-spacing: 0.45em;
  font-size: 13px;
  padding-left: 0.45em;
}
.loader-line {
  width: 130px;
  height: 1px;
  background: rgba(255, 255, 255, 0.14);
  overflow: hidden;
}
.loader-line span {
  display: block;
  height: 100%;
  width: 45%;
  background: var(--gold);
  animation: loaderSweep 1.25s ease-in-out infinite;
}
@keyframes loaderSweep {
  0% { transform: translateX(-120%); }
  100% { transform: translateX(320%); }
}
.loader-sub {
  font-size: 9px;
  letter-spacing: 0.28em;
  color: var(--muted);
  text-transform: uppercase;
}

/* ── Shared bits ────────────────────────────────────────── */
.eyebrow {
  display: flex;
  align-items: center;
  gap: 10px;
  font-size: 9.5px;
  font-weight: 700;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--gold-bright);
}
.eyebrow-line {
  display: inline-block;
  width: 28px;
  height: 1px;
  background: var(--gold);
  opacity: 0.7;
}

.brand-lockup {
  display: flex;
  align-items: center;
  gap: 13px;
}
.brand-mark {
  width: 44px;
  height: 44px;
  border: 1px solid rgba(216, 178, 116, 0.55);
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: 'Cormorant', serif;
  font-size: 23px;
  color: var(--gold-bright);
  background: rgba(8, 17, 20, 0.4);
  backdrop-filter: blur(8px);
}
.brand-mark.small {
  width: 36px;
  height: 36px;
  font-size: 19px;
}
.brand-words {
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.35em;
  line-height: 1.25;
}
.brand-words small {
  display: block;
  margin-top: 3px;
  font-size: 7px;
  font-weight: 600;
  letter-spacing: 0.28em;
  color: var(--gold);
}

.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 14px;
  height: 52px;
  padding: 0 24px;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 700;
  letter-spacing: 0.03em;
  transition: transform 0.22s ease, background 0.22s ease, border-color 0.22s ease, color 0.22s ease;
}
.btn:active {
  transform: scale(0.975);
}
.btn-gold {
  background: linear-gradient(135deg, #efd7a5 0%, #d8b274 50%, #c69b57 100%);
  color: #17201e;
  box-shadow: 0 12px 34px rgba(216, 178, 116, 0.16), inset 0 1px 0 rgba(255, 255, 255, 0.35);
}
.btn-gold:hover {
  background: linear-gradient(135deg, #f7e4bb 0%, #e1bd83 50%, #cfaa69 100%);
}
.btn-quiet {
  border: 1px solid var(--line);
  background: rgba(255, 255, 255, 0.035);
  color: var(--cream);
}
.btn-quiet:hover {
  background: rgba(255, 255, 255, 0.07);
}
.btn.small {
  height: 38px;
  padding: 0 16px;
  font-size: 10px;
}
.btn-arrow {
  font-size: 17px;
  line-height: 1;
  transition: transform 0.2s;
}
.btn:hover .btn-arrow {
  transform: translateX(3px);
}
.round-btn {
  width: 42px;
  height: 42px;
  border: 1px solid var(--line);
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(8, 17, 20, 0.42);
  backdrop-filter: blur(12px);
  color: var(--cream-soft);
  font-size: 15px;
}
.round-btn:hover {
  border-color: var(--gold);
  color: var(--gold-bright);
}

/* ── Select screen ──────────────────────────────────────── */
.select-screen {
  position: fixed;
  inset: 0;
  z-index: 20;
  display: flex;
  flex-direction: column;
  padding: calc(24px + var(--safe-top)) calc(28px + var(--safe-right)) calc(20px + var(--safe-bottom)) calc(28px + var(--safe-left));
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(4, 10, 12, 0.88) 0%, rgba(4, 10, 12, 0.62) 31%, rgba(4, 10, 12, 0.08) 62%, rgba(4, 10, 12, 0.1) 100%),
    linear-gradient(180deg, rgba(4, 10, 12, 0.36) 0%, transparent 30%, transparent 70%, rgba(4, 10, 12, 0.55) 100%);
}
.select-screen > * {
  pointer-events: auto;
}
.select-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  flex-shrink: 0;
}
.select-top-right {
  display: flex;
  gap: 10px;
}
.select-main {
  flex: 1;
  min-height: 0;
  display: flex;
  align-items: center;
  position: relative;
  padding-top: 18px;
}
.select-copy {
  width: min(455px, 44vw);
  max-height: 100%;
  display: flex;
  flex-direction: column;
  animation: revealUp 0.9s cubic-bezier(0.22, 1, 0.36, 1) both;
}
@keyframes revealUp {
  from { opacity: 0; transform: translateY(22px); }
  to { opacity: 1; transform: translateY(0); }
}
.select-copy h1 {
  margin: 17px 0 15px;
  font-family: 'Cormorant', serif;
  font-size: clamp(52px, 5.5vw, 86px);
  line-height: 0.88;
  font-weight: 500;
  letter-spacing: -0.045em;
  text-wrap: balance;
}
.select-copy h1 em {
  color: var(--gold-bright);
  font-weight: 400;
}
.select-lede {
  margin: 0 0 24px;
  max-width: 355px;
  font-size: 12.5px;
  line-height: 1.65;
  color: rgba(243, 235, 221, 0.68);
}
.family-picker {
  display: flex;
  flex-direction: column;
  gap: 7px;
  width: min(430px, 100%);
}
.family-option {
  position: relative;
  width: 100%;
  display: grid;
  grid-template-columns: 34px 1fr auto;
  gap: 13px;
  align-items: center;
  text-align: left;
  padding: 12px 15px 12px 13px;
  background: rgba(9, 19, 22, 0.44);
  border: 1px solid rgba(243, 235, 221, 0.1);
  border-radius: 13px;
  backdrop-filter: blur(18px);
  transition: background 0.25s, border-color 0.25s, transform 0.25s;
  overflow: hidden;
}
.family-option::before {
  content: '';
  position: absolute;
  left: 0;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--family-accent, var(--gold));
  opacity: 0;
  transition: opacity 0.25s;
}
.family-option:hover {
  background: rgba(16, 32, 37, 0.62);
  border-color: rgba(243, 235, 221, 0.22);
}
.family-option.active {
  background: linear-gradient(100deg, rgba(38, 54, 54, 0.7), rgba(9, 19, 22, 0.66));
  border-color: rgba(216, 178, 116, 0.58);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.05), 0 14px 38px rgba(0, 0, 0, 0.2);
}
.family-option.active::before {
  opacity: 1;
}
.family-index {
  font-family: 'Cormorant', serif;
  font-size: 22px;
  color: rgba(243, 235, 221, 0.36);
  text-align: center;
}
.family-option.active .family-index {
  color: var(--family-accent, var(--gold));
}
.family-option-copy {
  min-width: 0;
}
.family-option-copy b {
  display: block;
  font-family: 'Cormorant', serif;
  font-size: 20px;
  font-weight: 600;
  line-height: 1.05;
  letter-spacing: -0.01em;
}
.family-option-copy small {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 4px;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
}
.tier-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--family-accent);
  box-shadow: 0 0 8px var(--family-accent);
}
.family-money {
  text-align: right;
}
.family-money b {
  display: block;
  font-size: 12px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: -0.01em;
}
.family-money small {
  display: block;
  margin-top: 3px;
  font-size: 7px;
  letter-spacing: 0.16em;
  color: var(--muted);
  text-transform: uppercase;
}
.select-actions {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 17px;
  flex-wrap: wrap;
}
.select-actions .btn-gold {
  min-width: 228px;
}
.preview-label {
  position: absolute;
  right: 8px;
  bottom: 18px;
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 11px 16px;
  border-left: 1px solid rgba(216, 178, 116, 0.55);
  background: linear-gradient(90deg, rgba(8, 17, 20, 0.52), transparent);
  backdrop-filter: blur(8px);
  animation: revealUp 1s 0.15s both;
}
.preview-index {
  font-family: 'Cormorant', serif;
  font-size: 22px;
  color: var(--gold);
}
.preview-copy b {
  display: block;
  font-family: 'Cormorant', serif;
  font-size: 19px;
  font-weight: 500;
  letter-spacing: 0.01em;
}
.preview-copy small {
  display: block;
  margin-top: 2px;
  font-size: 8px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: var(--muted);
}
.select-footer {
  display: flex;
  justify-content: space-between;
  align-items: center;
  flex-shrink: 0;
  padding-top: 14px;
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: rgba(243, 235, 221, 0.36);
}
.footer-hint {
  color: rgba(243, 235, 221, 0.46);
}

/* ── Game HUD ───────────────────────────────────────────── */
.game-ui {
  position: fixed;
  inset: 0;
  z-index: 12;
  pointer-events: none;
}
.game-ui > * {
  pointer-events: auto;
}
.topbar {
  position: absolute;
  top: calc(16px + var(--safe-top));
  left: 0;
  right: 0;
  padding: 0 calc(22px + var(--safe-right)) 0 calc(22px + var(--safe-left));
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 14px;
  animation: hudIn 0.8s 0.1s both;
}
@keyframes hudIn {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}
.house-pill,
.wealth-pill,
.day-chip {
  border: 1px solid var(--line);
  background: var(--ink-glass);
  backdrop-filter: blur(20px) saturate(1.15);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.22), inset 0 1px 0 rgba(255, 255, 255, 0.04);
}
.house-pill {
  justify-self: start;
  display: flex;
  align-items: center;
  gap: 11px;
  height: 54px;
  padding: 0 15px 0 8px;
  border-radius: 999px;
  text-align: left;
  transition: border-color 0.2s, background 0.2s;
}
.house-pill:hover {
  border-color: rgba(216, 178, 116, 0.45);
  background: rgba(13, 27, 31, 0.82);
}
.crest {
  width: 38px;
  height: 38px;
  border-radius: 50%;
  border: 1px solid rgba(216, 178, 116, 0.52);
  background: radial-gradient(circle at 32% 28%, rgba(241, 215, 167, 0.22), rgba(12, 23, 26, 0.4));
  display: grid;
  place-items: center;
  font-family: 'Cormorant', serif;
  font-size: 20px;
  color: var(--gold-bright);
  flex-shrink: 0;
}
.house-pill-copy b {
  display: block;
  font-size: 11px;
  font-weight: 700;
  line-height: 1.15;
  letter-spacing: 0.01em;
}
.house-pill-copy small {
  display: block;
  margin-top: 3px;
  color: var(--gold);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.19em;
}
.chev {
  margin-left: 5px;
  color: var(--muted);
  font-size: 12px;
}
.day-chip {
  justify-self: center;
  display: flex;
  align-items: center;
  gap: 10px;
  height: 42px;
  padding: 0 17px;
  border-radius: 999px;
  transition: border-color 0.2s, background 0.2s;
}
.day-chip:hover {
  border-color: rgba(216, 178, 116, 0.45);
}
.day-dot {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 0 4px rgba(216, 178, 116, 0.12), 0 0 13px var(--gold);
}
.day-copy b {
  display: block;
  font-size: 8.5px;
  letter-spacing: 0.18em;
  font-weight: 700;
}
.day-copy small {
  display: block;
  margin-top: 2px;
  font-size: 7px;
  letter-spacing: 0.16em;
  color: var(--muted);
}
.wealth-pill {
  justify-self: end;
  display: flex;
  align-items: center;
  gap: 12px;
  height: 54px;
  padding: 0 9px 0 16px;
  border-radius: 14px;
  text-align: right;
  transition: border-color 0.2s, background 0.2s;
}
.wealth-pill:hover {
  border-color: rgba(216, 178, 116, 0.45);
  background: rgba(13, 27, 31, 0.82);
}
.wealth-copy small {
  display: block;
  font-size: 7px;
  letter-spacing: 0.2em;
  color: var(--muted);
  font-weight: 700;
}
.wealth-copy b {
  display: block;
  margin-top: 2px;
  font-size: clamp(16px, 1.7vw, 22px);
  line-height: 1.05;
  font-weight: 700;
  letter-spacing: -0.035em;
  font-variant-numeric: tabular-nums;
  color: var(--cream);
}
.income-chip {
  display: inline-flex;
  align-items: center;
  height: 27px;
  padding: 0 9px;
  border-radius: 8px;
  background: rgba(122, 163, 129, 0.16);
  color: #b6d3b7;
  font-size: 8px;
  font-weight: 700;
  letter-spacing: 0.02em;
  white-space: nowrap;
}

.tutorial {
  position: absolute;
  top: calc(84px + var(--safe-top));
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 12px 9px 14px;
  border: 1px solid rgba(243, 235, 221, 0.1);
  border-radius: 999px;
  background: rgba(5, 12, 14, 0.58);
  backdrop-filter: blur(16px);
  font-size: 8.5px;
  letter-spacing: 0.02em;
  color: rgba(243, 235, 221, 0.64);
  white-space: nowrap;
  animation: hudIn 0.8s 0.8s both;
  transition: opacity 0.4s, transform 0.4s;
}
.tutorial.hide {
  opacity: 0;
  transform: translate(-50%, -8px);
  pointer-events: none;
}
.tutorial-dot {
  width: 4px;
  height: 4px;
  border-radius: 50%;
  background: var(--gold);
}
.tutorial button {
  margin-left: 3px;
  color: var(--muted);
  font-size: 13px;
  line-height: 1;
  padding: 0 2px;
}

.estate-card {
  position: absolute;
  left: calc(22px + var(--safe-left));
  bottom: calc(105px + var(--safe-bottom));
  width: 306px;
  padding: 20px 20px 18px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: linear-gradient(150deg, rgba(14, 28, 32, 0.88), rgba(7, 16, 19, 0.7));
  backdrop-filter: blur(22px) saturate(1.1);
  box-shadow: var(--shadow);
  animation: hudIn 0.8s 0.25s both;
}
.card-kicker {
  display: flex;
  align-items: center;
  gap: 7px;
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.21em;
  color: var(--gold);
}
.live-dot {
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--gold);
  box-shadow: 0 0 8px var(--gold);
}
.estate-card h2 {
  margin: 9px 0 1px;
  font-family: 'Cormorant', serif;
  font-size: 31px;
  line-height: 1;
  font-weight: 500;
  letter-spacing: -0.025em;
}
.estate-card > p {
  margin: 0;
  font-size: 8px;
  letter-spacing: 0.15em;
  text-transform: uppercase;
  color: var(--muted);
}
.estate-card .mood-line {
  margin-top: 12px;
  padding-top: 12px;
  border-top: 1px solid var(--line);
  font-family: 'Cormorant', serif;
  font-size: 14.5px;
  font-style: italic;
  line-height: 1.32;
  letter-spacing: 0;
  text-transform: none;
  color: rgba(243, 235, 221, 0.72);
}
.stat-row {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 12px;
  margin-top: 13px;
}
.stat > span {
  display: flex;
  align-items: center;
  gap: 5px;
  font-size: 7.5px;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: var(--muted);
}
.stat > span b {
  margin-left: auto;
  font-size: 9px;
  color: var(--cream);
}
.heart-icon,
.star-icon {
  font-style: normal;
  font-size: 8px;
  color: var(--gold);
}
.stat-bar {
  height: 3px;
  margin-top: 6px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.09);
  overflow: hidden;
}
.stat-bar i {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: linear-gradient(90deg, #b9a16f, var(--gold-bright));
  transition: width 0.6s cubic-bezier(0.22, 1, 0.36, 1);
}
.stat-bar.prestige i {
  background: linear-gradient(90deg, #749083, #b8d1bf);
}
.moment-btn {
  width: 100%;
  margin-top: 14px;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 9px 10px;
  border: 1px solid rgba(216, 178, 116, 0.2);
  border-radius: 10px;
  background: rgba(216, 178, 116, 0.07);
  text-align: left;
  transition: background 0.2s, border-color 0.2s;
}
.moment-btn:hover {
  background: rgba(216, 178, 116, 0.12);
  border-color: rgba(216, 178, 116, 0.36);
}
.moment-btn:disabled {
  opacity: 0.48;
  cursor: default;
}
.moment-icon {
  width: 26px;
  height: 26px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(216, 178, 116, 0.14);
  color: var(--gold-bright);
  font-size: 12px;
}
.moment-btn b {
  display: block;
  font-size: 9px;
  font-weight: 700;
}
.moment-btn small {
  display: block;
  margin-top: 2px;
  font-size: 7.5px;
  color: var(--muted);
}

.next-day-btn {
  position: absolute;
  right: calc(22px + var(--safe-right));
  bottom: calc(105px + var(--safe-bottom));
  display: flex;
  align-items: center;
  gap: 10px;
  height: 48px;
  padding: 0 17px 0 10px;
  border: 1px solid rgba(216, 178, 116, 0.3);
  border-radius: 999px;
  background: rgba(13, 27, 31, 0.82);
  backdrop-filter: blur(20px);
  box-shadow: 0 12px 30px rgba(0, 0, 0, 0.28);
  text-align: left;
  transition: border-color 0.2s, background 0.2s, transform 0.2s;
  animation: hudIn 0.8s 0.35s both;
}
.next-day-btn:hover {
  border-color: rgba(216, 178, 116, 0.7);
  background: rgba(20, 39, 43, 0.9);
}
.next-day-btn:active {
  transform: scale(0.97);
}
.next-day-icon {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(216, 178, 116, 0.15);
  color: var(--gold-bright);
  font-size: 15px;
}
.next-day-btn b {
  display: block;
  font-size: 9px;
  font-weight: 700;
}
.next-day-btn small {
  display: block;
  margin-top: 1px;
  font-size: 7px;
  color: var(--muted);
}

.dock {
  position: absolute;
  left: 50%;
  bottom: calc(18px + var(--safe-bottom));
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 2px;
  height: 64px;
  padding: 6px;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: rgba(7, 16, 19, 0.8);
  backdrop-filter: blur(24px) saturate(1.15);
  box-shadow: 0 18px 54px rgba(0, 0, 0, 0.42), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  animation: dockIn 0.8s 0.3s both;
}
@keyframes dockIn {
  from { opacity: 0; transform: translate(-50%, 18px); }
  to { opacity: 1; transform: translate(-50%, 0); }
}
.dock-item {
  position: relative;
  min-width: 72px;
  height: 52px;
  padding: 5px 12px;
  border-radius: 12px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 3px;
  color: rgba(243, 235, 221, 0.5);
  font-size: 8px;
  font-weight: 600;
  letter-spacing: 0.03em;
  transition: color 0.2s, background 0.2s;
}
.dock-item:hover {
  color: var(--cream);
  background: rgba(255, 255, 255, 0.04);
}
.dock-item.active {
  color: var(--gold-bright);
  background: linear-gradient(180deg, rgba(216, 178, 116, 0.13), rgba(216, 178, 116, 0.04));
}
.dock-item.active::after {
  content: '';
  position: absolute;
  bottom: 4px;
  left: 50%;
  transform: translateX(-50%);
  width: 14px;
  height: 2px;
  border-radius: 999px;
  background: var(--gold);
  box-shadow: 0 0 8px rgba(216, 178, 116, 0.6);
}
.dock-icon {
  width: 19px;
  height: 19px;
  display: grid;
  place-items: center;
}
.dock-icon svg {
  width: 18px;
  height: 18px;
  stroke-width: 1.45;
}

/* ── Panel ──────────────────────────────────────────────── */
.panel {
  position: fixed;
  inset: 0;
  z-index: 60;
}
.panel-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(2, 8, 10, 0.62);
  backdrop-filter: blur(9px);
  animation: fadeIn 0.3s both;
}
@keyframes fadeIn {
  from { opacity: 0; }
  to { opacity: 1; }
}
.panel-sheet {
  position: absolute;
  top: calc(20px + var(--safe-top));
  right: calc(20px + var(--safe-right));
  bottom: calc(20px + var(--safe-bottom));
  width: min(1080px, calc(100vw - 40px));
  border: 1px solid rgba(243, 235, 221, 0.13);
  border-radius: 26px;
  background:
    radial-gradient(ellipse at 90% 0%, rgba(58, 78, 72, 0.18), transparent 45%),
    linear-gradient(155deg, #0d1a1e 0%, #091417 52%, #081215 100%);
  box-shadow: 0 40px 120px rgba(0, 0, 0, 0.64), inset 0 1px 0 rgba(255, 255, 255, 0.04);
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: sheetIn 0.42s cubic-bezier(0.22, 1, 0.36, 1) both;
}
@keyframes sheetIn {
  from { opacity: 0; transform: translateX(28px) scale(0.985); }
  to { opacity: 1; transform: translateX(0) scale(1); }
}
.panel-head {
  flex-shrink: 0;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 20px;
  padding: 36px 44px 22px;
  border-bottom: 1px solid var(--line);
}
.panel-head h2 {
  margin: 12px 0 2px;
  font-family: 'Cormorant', serif;
  font-size: clamp(38px, 4.4vw, 60px);
  line-height: 0.92;
  font-weight: 500;
  letter-spacing: -0.035em;
}
.panel-head p {
  margin: 8px 0 0;
  color: var(--muted);
  font-size: 10.5px;
  line-height: 1.5;
}
.panel-close {
  width: 40px;
  height: 40px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.035);
  font-size: 20px;
  line-height: 1;
  color: var(--cream-soft);
  transition: background 0.2s, border-color 0.2s;
}
.panel-close:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: var(--line-strong);
}
.panel-body {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  padding: 28px 44px 48px;
  overscroll-behavior: contain;
  scrollbar-width: thin;
  scrollbar-color: rgba(216, 178, 116, 0.3) transparent;
}
.panel-body::-webkit-scrollbar {
  width: 5px;
}
.panel-body::-webkit-scrollbar-thumb {
  background: rgba(216, 178, 116, 0.28);
  border-radius: 999px;
}

.panel-section {
  margin-bottom: 34px;
}
.panel-section:last-child {
  margin-bottom: 0;
}
.section-head {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 20px;
  margin-bottom: 14px;
}
.section-head h3 {
  margin: 0;
  font-family: 'Cormorant', serif;
  font-size: 27px;
  font-weight: 500;
  letter-spacing: -0.02em;
}
.section-head p {
  margin: 0;
  font-size: 9px;
  color: var(--muted);
}
.section-label {
  display: block;
  margin-bottom: 10px;
  font-size: 7.5px;
  font-weight: 700;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold);
}
.split {
  display: grid;
  grid-template-columns: 1.15fr 0.85fr;
  gap: 16px;
}
.split-even {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.panel-card {
  position: relative;
  padding: 20px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.025);
  overflow: hidden;
}
.panel-card.warm {
  background: linear-gradient(145deg, rgba(216, 178, 116, 0.1), rgba(255, 255, 255, 0.025));
  border-color: rgba(216, 178, 116, 0.25);
}

.stat-big-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 10px;
}
.stat-big {
  padding: 16px 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.022);
}
.stat-big small {
  display: block;
  font-size: 7px;
  letter-spacing: 0.18em;
  color: var(--muted);
  font-weight: 700;
}
.stat-big b {
  display: block;
  margin-top: 7px;
  font-family: 'Cormorant', serif;
  font-size: 27px;
  font-weight: 500;
  line-height: 1;
}
.stat-big i {
  display: block;
  margin-top: 4px;
  font-size: 7.5px;
  font-style: normal;
  color: var(--muted);
}

.member-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}
.member-card {
  position: relative;
  padding: 17px;
  border: 1px solid var(--line);
  border-radius: 16px;
  background: linear-gradient(150deg, rgba(255, 255, 255, 0.04), rgba(255, 255, 255, 0.015));
  overflow: hidden;
  transition: border-color 0.2s, transform 0.2s;
}
.member-card:hover {
  border-color: rgba(216, 178, 116, 0.3);
}
.member-card::after {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  background: linear-gradient(90deg, var(--m-top, var(--gold)), transparent 72%);
  opacity: 0.75;
}
.member-top {
  display: flex;
  align-items: center;
  gap: 12px;
}
.member-avatar {
  width: 48px;
  height: 48px;
  flex-shrink: 0;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: 'Cormorant', serif;
  font-size: 20px;
  color: #fff6e9;
  background: linear-gradient(145deg, var(--m-top, #8d7a5d), var(--m-bottom, #3c4d48));
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.2), 0 6px 18px rgba(0, 0, 0, 0.25);
}
.member-name b {
  display: block;
  font-family: 'Cormorant', serif;
  font-size: 24px;
  font-weight: 600;
  line-height: 1;
}
.member-name small {
  display: block;
  margin-top: 4px;
  font-size: 7.5px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--muted);
}
.member-role {
  margin: 13px 0 0;
  font-size: 10px;
  line-height: 1.45;
  color: rgba(243, 235, 221, 0.8);
}
.member-outfit {
  display: flex;
  align-items: flex-start;
  gap: 6px;
  margin-top: 9px;
  padding-top: 9px;
  border-top: 1px solid var(--line);
  font-size: 8.5px;
  line-height: 1.4;
  color: var(--muted);
}
.member-outfit::before {
  content: '';
  width: 6px;
  height: 6px;
  margin-top: 3px;
  border-radius: 50%;
  flex-shrink: 0;
  background: var(--m-top, var(--gold));
}
.member-chip {
  display: inline-flex;
  margin-top: 11px;
  padding: 4px 8px;
  border-radius: 999px;
  background: rgba(216, 178, 116, 0.09);
  border: 1px solid rgba(216, 178, 116, 0.18);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--gold-bright);
}

.profile-quote {
  margin: 0;
  font-family: 'Cormorant', serif;
  font-size: 22px;
  font-style: italic;
  line-height: 1.25;
  color: var(--gold-bright);
}
.profile-line {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  padding: 9px 0;
  border-bottom: 1px solid var(--line);
  font-size: 9px;
}
.profile-line:last-child {
  border-bottom: 0;
}
.profile-line span {
  color: var(--muted);
}
.profile-line b {
  text-align: right;
  font-weight: 600;
  font-size: 9px;
}

.house-visual {
  position: relative;
  min-height: 178px;
  padding: 22px;
  border-radius: 16px;
  overflow: hidden;
  border: 1px solid rgba(216, 178, 116, 0.22);
  background:
    linear-gradient(180deg, rgba(27, 43, 46, 0.88), rgba(9, 19, 22, 0.92)),
    radial-gradient(ellipse at 78% 22%, rgba(216, 178, 116, 0.24), transparent 40%);
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}
.house-visual::before {
  content: '';
  position: absolute;
  right: -20px;
  bottom: -14px;
  width: 220px;
  height: 115px;
  background:
    linear-gradient(90deg, transparent 0 10%, rgba(243, 235, 221, 0.18) 10% 12%, transparent 12% 22%, rgba(243, 235, 221, 0.22) 22% 24%, transparent 24% 38%, rgba(243, 235, 221, 0.16) 38% 40%, transparent 40%),
    linear-gradient(180deg, transparent 0 40%, rgba(243, 235, 221, 0.12) 40% 43%, transparent 43%);
  opacity: 0.6;
  clip-path: polygon(0 100%, 0 64%, 12% 64%, 12% 42%, 30% 42%, 30% 52%, 44% 52%, 44% 22%, 66% 22%, 66% 46%, 80% 46%, 80% 12%, 92% 12%, 92% 46%, 100% 46%, 100% 100%);
}
.house-visual .hv-kicker {
  position: relative;
  font-size: 7.5px;
  letter-spacing: 0.22em;
  color: var(--gold);
  font-weight: 700;
}
.house-visual h3 {
  position: relative;
  margin: 7px 0 0;
  font-family: 'Cormorant', serif;
  font-size: 36px;
  font-weight: 500;
  line-height: 0.95;
  letter-spacing: -0.03em;
}
.house-visual p {
  position: relative;
  margin: 8px 0 0;
  max-width: 330px;
  font-size: 9px;
  line-height: 1.55;
  color: var(--muted);
}
.house-specs {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 8px;
  margin-top: 14px;
}
.spec {
  padding: 9px 10px;
  border: 1px solid var(--line);
  border-radius: 9px;
  background: rgba(255, 255, 255, 0.025);
}
.spec small {
  display: block;
  color: var(--muted);
  font-size: 6.5px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
}
.spec b {
  display: block;
  margin-top: 4px;
  font-size: 10px;
  font-weight: 600;
}

.asset-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}
.asset-item {
  display: flex;
  gap: 12px;
  padding: 15px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.022);
}
.asset-icon {
  width: 34px;
  height: 34px;
  flex-shrink: 0;
  border-radius: 10px;
  display: grid;
  place-items: center;
  background: rgba(216, 178, 116, 0.09);
  border: 1px solid rgba(216, 178, 116, 0.16);
  color: var(--gold-bright);
}
.asset-icon svg {
  width: 18px;
  height: 18px;
}
.asset-copy {
  min-width: 0;
}
.asset-copy small {
  display: block;
  font-size: 6.5px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}
.asset-copy b {
  display: block;
  margin-top: 3px;
  font-size: 10.5px;
  font-weight: 600;
  line-height: 1.35;
}
.asset-copy p {
  margin: 3px 0 0;
  font-size: 8px;
  line-height: 1.45;
  color: var(--muted);
}

.list-card {
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.02);
}
.list-row {
  display: flex;
  align-items: center;
  gap: 13px;
  padding: 14px 16px;
  border-bottom: 1px solid var(--line);
}
.list-row:last-child {
  border-bottom: 0;
}
.list-num {
  width: 25px;
  height: 25px;
  flex-shrink: 0;
  display: grid;
  place-items: center;
  border: 1px solid var(--line);
  border-radius: 50%;
  font-family: 'Cormorant', serif;
  font-size: 13px;
  color: var(--gold);
}
.list-copy {
  flex: 1;
  min-width: 0;
}
.list-copy b {
  display: block;
  font-size: 10px;
  font-weight: 600;
}
.list-copy small {
  display: block;
  margin-top: 2px;
  font-size: 8px;
  color: var(--muted);
}
.list-value {
  text-align: right;
}
.list-value b {
  display: block;
  font-size: 10px;
  font-weight: 600;
  font-variant-numeric: tabular-nums;
}
.list-value small {
  display: block;
  margin-top: 2px;
  font-size: 7px;
  color: var(--muted);
}

.sig-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 9px;
}
.sig-item {
  padding: 13px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.02);
}
.sig-item small {
  display: block;
  font-size: 6.5px;
  letter-spacing: 0.16em;
  color: var(--gold);
  text-transform: uppercase;
}
.sig-item b {
  display: block;
  margin-top: 5px;
  font-size: 9px;
  line-height: 1.4;
  font-weight: 500;
}

.insurance-tag {
  display: inline-block;
  padding: 4px 8px;
  border: 1px solid rgba(145, 169, 152, 0.3);
  border-radius: 999px;
  background: rgba(145, 169, 152, 0.08);
  color: #bdd4c4;
  font-size: 7px;
  letter-spacing: 0.08em;
}

/* Travel panel */
.travel-intro {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 16px;
}
.aircraft-chip {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 9px 13px;
  border: 1px solid rgba(216, 178, 116, 0.2);
  border-radius: 999px;
  background: rgba(216, 178, 116, 0.06);
  font-size: 8px;
  color: var(--gold-bright);
  white-space: nowrap;
}
.aircraft-chip svg {
  width: 15px;
  height: 15px;
}
.destination-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 11px;
}
.destination-card {
  position: relative;
  min-height: 140px;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: linear-gradient(160deg, var(--dest-a, #2b3d41), var(--dest-b, #102024));
  overflow: hidden;
  text-align: left;
  transition: transform 0.22s, border-color 0.22s, box-shadow 0.22s;
}
.destination-card::before {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(180deg, transparent 30%, rgba(3, 9, 11, 0.82));
}
.destination-card:hover {
  transform: translateY(-3px);
  border-color: rgba(216, 178, 116, 0.45);
  box-shadow: 0 14px 30px rgba(0, 0, 0, 0.26);
}
.destination-card.selected {
  border-color: var(--gold);
  box-shadow: 0 0 0 1px rgba(216, 178, 116, 0.24), 0 14px 34px rgba(0, 0, 0, 0.3);
}
.dest-art {
  position: absolute;
  right: -2px;
  top: 3px;
  width: 100px;
  height: 84px;
  opacity: 0.6;
  color: rgba(243, 235, 221, 0.52);
}
.dest-art svg {
  width: 100%;
  height: 100%;
}
.dest-content {
  position: relative;
  height: 112px;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
}
.dest-code {
  position: absolute;
  top: 0;
  left: 0;
  font-size: 6.5px;
  letter-spacing: 0.2em;
  color: rgba(255, 255, 255, 0.62);
  font-weight: 700;
}
.dest-content b {
  font-family: 'Cormorant', serif;
  font-size: 25px;
  line-height: 0.95;
  font-weight: 500;
  letter-spacing: -0.02em;
}
.dest-content small {
  display: block;
  margin-top: 4px;
  font-size: 6.5px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(243, 235, 221, 0.6);
}
.dest-price {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-top: 9px;
  font-size: 7px;
  color: rgba(243, 235, 221, 0.6);
}
.dest-price b {
  color: var(--gold-bright);
  font-size: 9px;
}
.destination-detail {
  margin-top: 18px;
  padding: 20px;
  border: 1px solid rgba(216, 178, 116, 0.25);
  border-radius: 18px;
  background: linear-gradient(150deg, rgba(216, 178, 116, 0.08), rgba(255, 255, 255, 0.022));
  animation: revealUp 0.35s both;
}
.dd-head {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  margin-bottom: 16px;
}
.dd-head h3 {
  margin: 0;
  font-family: 'Cormorant', serif;
  font-size: 34px;
  font-weight: 500;
  line-height: 1;
  letter-spacing: -0.03em;
}
.dd-head p {
  margin: 6px 0 0;
  max-width: 530px;
  font-size: 9px;
  line-height: 1.55;
  color: var(--muted);
}
.dd-tag {
  align-self: flex-start;
  padding: 5px 9px;
  border: 1px solid rgba(216, 178, 116, 0.24);
  border-radius: 999px;
  font-size: 7px;
  letter-spacing: 0.13em;
  text-transform: uppercase;
  color: var(--gold-bright);
  white-space: nowrap;
}
.class-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 10px;
}
.class-card {
  position: relative;
  padding: 14px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.025);
  text-align: left;
  transition: border-color 0.2s, background 0.2s;
}
.class-card:hover {
  border-color: rgba(216, 178, 116, 0.35);
}
.class-card.selected {
  border-color: var(--gold);
  background: rgba(216, 178, 116, 0.09);
}
.class-card .recommend {
  position: absolute;
  top: -7px;
  right: 9px;
  padding: 3px 7px;
  border-radius: 999px;
  background: var(--gold);
  color: #18211e;
  font-size: 5.8px;
  font-weight: 800;
  letter-spacing: 0.07em;
}
.class-card b {
  display: block;
  font-family: 'Cormorant', serif;
  font-size: 21px;
  font-weight: 600;
  line-height: 1;
}
.class-card .class-kicker {
  display: block;
  margin-top: 4px;
  font-size: 5.8px;
  letter-spacing: 0.15em;
  color: var(--gold);
  font-weight: 700;
}
.class-card .class-price {
  display: block;
  margin-top: 9px;
  font-size: 11px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
}
.class-card small {
  display: block;
  margin-top: 3px;
  font-size: 6.8px;
  color: var(--muted);
}
.class-perks {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 8px;
}
.class-perks span {
  padding: 3px 6px;
  border-radius: 5px;
  background: rgba(255, 255, 255, 0.05);
  font-size: 6.2px;
  color: rgba(243, 235, 221, 0.62);
}
.booking-bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  margin-top: 14px;
  padding-top: 14px;
  border-top: 1px solid var(--line);
}
.booking-total small {
  display: block;
  font-size: 6.5px;
  letter-spacing: 0.16em;
  color: var(--muted);
  text-transform: uppercase;
}
.booking-total b {
  display: block;
  margin-top: 3px;
  font-family: 'Cormorant', serif;
  font-size: 27px;
  font-weight: 500;
  line-height: 1;
  color: var(--gold-bright);
  font-variant-numeric: tabular-nums;
}
.booking-bar .btn {
  height: 44px;
  font-size: 10px;
  padding: 0 20px;
}
.booking-bar .btn:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}
.booking-note {
  margin-top: 8px;
  font-size: 7.5px;
  color: var(--muted);
}
.booking-note.warn {
  color: #e5b29b;
}

/* Ledger */
.ledger-hero {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 22px;
  padding: 21px 23px;
  border: 1px solid rgba(216, 178, 116, 0.22);
  border-radius: 18px;
  background:
    radial-gradient(ellipse at 90% 0%, rgba(216, 178, 116, 0.13), transparent 45%),
    rgba(255, 255, 255, 0.025);
}
.ledger-hero small {
  display: block;
  font-size: 7px;
  letter-spacing: 0.2em;
  color: var(--muted);
  text-transform: uppercase;
}
.ledger-hero .big-money {
  display: block;
  margin-top: 5px;
  font-family: 'Cormorant', serif;
  font-size: clamp(38px, 4.5vw, 57px);
  line-height: 0.9;
  font-weight: 500;
  letter-spacing: -0.03em;
  font-variant-numeric: tabular-nums;
}
.ledger-hero-right {
  text-align: right;
}
.ledger-hero-right b {
  display: block;
  font-size: 16px;
  color: #b8d7bc;
  font-variant-numeric: tabular-nums;
}
.ledger-hero-right small {
  margin-top: 4px;
}
.income-list .list-row {
  padding: 12px 15px;
}
.ledger-actions {
  display: flex;
  justify-content: flex-end;
  margin-top: 14px;
}
.switch-household {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  margin-top: 30px;
  padding: 17px 19px;
  border: 1px dashed rgba(216, 178, 116, 0.26);
  border-radius: 14px;
  background: rgba(216, 178, 116, 0.04);
}
.switch-household p {
  margin: 0;
  font-size: 9px;
  line-height: 1.5;
  color: var(--muted);
}
.switch-household b {
  display: block;
  margin-bottom: 3px;
  font-size: 11px;
  color: var(--cream);
}

/* ── Flight / vacation ──────────────────────────────────── */
.flight-screen {
  position: fixed;
  inset: 0;
  z-index: 55;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: calc(22px + var(--safe-top)) calc(26px + var(--safe-right)) calc(20px + var(--safe-bottom)) calc(26px + var(--safe-left));
  pointer-events: none;
  background:
    linear-gradient(180deg, rgba(4, 10, 13, 0.78) 0%, transparent 28%, transparent 66%, rgba(4, 10, 13, 0.86) 100%),
    radial-gradient(ellipse at 50% 100%, rgba(240, 194, 142, 0.13), transparent 52%);
  animation: fadeIn 0.7s both;
}
.flight-screen > * {
  pointer-events: auto;
}
.flight-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
}
.flight-brand {
  display: flex;
  align-items: center;
  gap: 11px;
}
.flight-brand b {
  display: block;
  font-size: 9px;
  letter-spacing: 0.22em;
}
.flight-brand small {
  display: block;
  margin-top: 3px;
  font-size: 7px;
  letter-spacing: 0.18em;
  color: var(--gold);
}
.flight-center {
  width: min(780px, 90vw);
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 19px;
  margin-top: auto;
  margin-bottom: auto;
  animation: revealUp 1s 0.1s both;
}
.flight-route {
  display: flex;
  align-items: center;
  width: 100%;
  gap: 20px;
}
.airport b {
  display: block;
  font-family: 'Cormorant', serif;
  font-size: clamp(38px, 5.2vw, 64px);
  font-weight: 500;
  line-height: 1;
  letter-spacing: 0.03em;
}
.airport small {
  display: block;
  margin-top: 4px;
  font-size: 6.5px;
  letter-spacing: 0.22em;
  color: var(--muted);
}
.airport.right {
  text-align: right;
}
.route-track {
  position: relative;
  flex: 1;
  height: 1px;
  background: rgba(243, 235, 221, 0.18);
}
.route-track::before {
  content: '';
  position: absolute;
  left: 0;
  top: -2px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  background: var(--gold);
}
.route-track::after {
  content: '';
  position: absolute;
  right: 0;
  top: -2px;
  width: 5px;
  height: 5px;
  border-radius: 50%;
  border: 1px solid rgba(216, 178, 116, 0.7);
}
.route-track i {
  position: absolute;
  left: 0;
  top: -0.5px;
  height: 2px;
  background: linear-gradient(90deg, rgba(216, 178, 116, 0.2), var(--gold));
  width: 0%;
  box-shadow: 0 0 12px rgba(216, 178, 116, 0.8);
}
.route-plane {
  position: absolute;
  top: 50%;
  left: 0%;
  transform: translate(-50%, -50%);
  width: 20px;
  height: 20px;
  color: var(--gold-bright);
  transition: left 0.2s linear;
}
.route-plane svg {
  width: 20px;
  height: 20px;
  transform: rotate(90deg);
}
.flight-status {
  display: flex;
  justify-content: space-between;
  width: 100%;
  max-width: 470px;
  font-size: 8px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--gold-bright);
}
.flight-perks {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 7px;
}
.flight-perks span {
  padding: 6px 11px;
  border: 1px solid var(--line);
  border-radius: 999px;
  background: rgba(8, 17, 20, 0.4);
  backdrop-filter: blur(12px);
  font-size: 7px;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(243, 235, 221, 0.66);
}
.flight-bottom {
  display: flex;
  justify-content: space-between;
  font-size: 7px;
  letter-spacing: 0.2em;
  text-transform: uppercase;
  color: var(--muted);
}

.vacation-screen {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: flex;
  flex-direction: column;
  padding: calc(24px + var(--safe-top)) calc(28px + var(--safe-right)) calc(20px + var(--safe-bottom)) calc(28px + var(--safe-left));
  pointer-events: none;
  background:
    linear-gradient(90deg, rgba(4, 10, 12, 0.88) 0%, rgba(4, 10, 12, 0.55) 38%, transparent 66%),
    linear-gradient(180deg, rgba(4, 10, 12, 0.28), transparent 32%, transparent 72%, rgba(4, 10, 12, 0.65));
  animation: fadeIn 0.8s both;
}
.vacation-screen > * {
  pointer-events: auto;
}
.vacation-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
}
.vacation-badge {
  padding: 8px 13px;
  border: 1px solid rgba(216, 178, 116, 0.36);
  border-radius: 999px;
  background: rgba(8, 17, 20, 0.42);
  backdrop-filter: blur(12px);
  color: var(--gold-bright);
  font-size: 7px;
  font-weight: 700;
  letter-spacing: 0.2em;
}
.vacation-main {
  flex: 1;
  display: flex;
  align-items: center;
  min-height: 0;
}
.vacation-card {
  width: min(510px, 45vw);
  animation: revealUp 0.9s 0.1s both;
}
.vacation-card h1 {
  margin: 13px 0 0;
  font-family: 'Cormorant', serif;
  font-size: clamp(60px, 8vw, 112px);
  line-height: 0.8;
  font-weight: 500;
  letter-spacing: -0.05em;
}
.vacation-country {
  margin: 13px 0 0;
  font-size: 8px;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: var(--gold);
}
.vacation-note {
  margin: 18px 0 0;
  max-width: 390px;
  font-family: 'Cormorant', serif;
  font-size: 19px;
  font-style: italic;
  line-height: 1.35;
  color: rgba(243, 235, 221, 0.76);
}
.vacation-details {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-top: 22px;
  padding-top: 18px;
  border-top: 1px solid var(--line);
  max-width: 420px;
}
.vacation-details > div {
  display: flex;
  justify-content: space-between;
  gap: 16px;
  align-items: baseline;
}
.vacation-details small {
  font-size: 6.5px;
  letter-spacing: 0.16em;
  color: var(--muted);
  white-space: nowrap;
}
.vacation-details b {
  font-size: 9px;
  font-weight: 600;
  text-align: right;
}
.vacation-actions {
  display: flex;
  align-items: center;
  gap: 15px;
  margin-top: 22px;
  flex-wrap: wrap;
}
.vacation-bonus {
  font-size: 8px;
  color: #b7d3bb;
}
.vacation-footer {
  display: flex;
  justify-content: space-between;
  gap: 18px;
  font-size: 7px;
  letter-spacing: 0.18em;
  text-transform: uppercase;
  color: rgba(243, 235, 221, 0.38);
}

/* ── Intro / toast / switch ─────────────────────────────── */
.intro {
  position: fixed;
  inset: 0;
  z-index: 45;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  gap: 8px;
  pointer-events: none;
  background: radial-gradient(ellipse at center, rgba(5, 12, 14, 0.45) 0%, rgba(5, 12, 14, 0.88) 72%);
  animation: introFade 2.6s ease both;
}
@keyframes introFade {
  0% { opacity: 0; }
  15% { opacity: 1; }
  76% { opacity: 1; }
  100% { opacity: 0; visibility: hidden; }
}
.intro-crest {
  width: 55px;
  height: 55px;
  border: 1px solid rgba(216, 178, 116, 0.6);
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: 'Cormorant', serif;
  font-size: 25px;
  color: var(--gold-bright);
  margin-bottom: 10px;
}
.intro-kicker {
  font-size: 8px;
  letter-spacing: 0.3em;
  color: var(--gold);
}
.intro-name {
  font-family: 'Cormorant', serif;
  font-size: clamp(46px, 7vw, 82px);
  font-weight: 500;
  line-height: 0.9;
  letter-spacing: -0.04em;
}
.intro-tier {
  font-size: 7.5px;
  letter-spacing: 0.27em;
  color: var(--muted);
}

.toast-stack {
  position: fixed;
  z-index: 80;
  top: calc(86px + var(--safe-top));
  right: calc(22px + var(--safe-right));
  display: flex;
  flex-direction: column;
  gap: 8px;
  width: min(310px, calc(100vw - 36px));
  pointer-events: none;
}
.toast {
  display: flex;
  gap: 11px;
  align-items: flex-start;
  padding: 13px 15px;
  border: 1px solid rgba(216, 178, 116, 0.28);
  border-radius: 12px;
  background: rgba(9, 20, 23, 0.9);
  backdrop-filter: blur(20px);
  box-shadow: 0 16px 40px rgba(0, 0, 0, 0.35);
  animation: toastIn 0.4s cubic-bezier(0.22, 1, 0.36, 1) both;
}
.toast.leaving {
  animation: toastOut 0.35s ease forwards;
}
@keyframes toastIn {
  from { opacity: 0; transform: translateY(-8px) scale(0.98); }
  to { opacity: 1; transform: translateY(0) scale(1); }
}
@keyframes toastOut {
  to { opacity: 0; transform: translateY(-8px); }
}
.toast-icon {
  width: 24px;
  height: 24px;
  flex-shrink: 0;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(216, 178, 116, 0.14);
  color: var(--gold-bright);
  font-size: 11px;
}
.toast b {
  display: block;
  font-size: 9.5px;
  font-weight: 700;
}
.toast p {
  margin: 3px 0 0;
  font-size: 8px;
  line-height: 1.45;
  color: var(--muted);
}

.switch-modal {
  position: fixed;
  inset: 0;
  z-index: 90;
  display: grid;
  place-items: center;
  padding: 20px;
}
.switch-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(2, 8, 10, 0.7);
  backdrop-filter: blur(10px);
}
.switch-card {
  position: relative;
  width: min(460px, 100%);
  padding: 30px;
  border: 1px solid var(--line);
  border-radius: 22px;
  background: linear-gradient(150deg, #101f23, #081215);
  box-shadow: var(--shadow);
  animation: revealUp 0.4s both;
}
.switch-card h2 {
  margin: 12px 0 5px;
  font-family: 'Cormorant', serif;
  font-size: 38px;
  font-weight: 500;
  line-height: 0.95;
  letter-spacing: -0.03em;
}
.switch-card > p {
  margin: 0 0 18px;
  font-size: 9px;
  line-height: 1.5;
  color: var(--muted);
}
.switch-options {
  display: flex;
  flex-direction: column;
  gap: 7px;
  margin-bottom: 15px;
}
.switch-option {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  padding: 12px 13px;
  border: 1px solid var(--line);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.025);
  text-align: left;
  transition: border-color 0.2s, background 0.2s;
}
.switch-option:hover {
  border-color: rgba(216, 178, 116, 0.42);
  background: rgba(255, 255, 255, 0.05);
}
.switch-option.current {
  border-color: rgba(216, 178, 116, 0.4);
  background: rgba(216, 178, 116, 0.07);
}
.switch-option-left {
  display: flex;
  align-items: center;
  gap: 10px;
}
.switch-option .mini-crest {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  border: 1px solid rgba(216, 178, 116, 0.35);
  font-family: 'Cormorant', serif;
  font-size: 16px;
  color: var(--gold);
}
.switch-option b {
  display: block;
  font-size: 10px;
}
.switch-option small {
  display: block;
  margin-top: 2px;
  font-size: 7px;
  color: var(--muted);
  letter-spacing: 0.1em;
  text-transform: uppercase;
}
.switch-option .so-money {
  font-size: 9px;
  font-variant-numeric: tabular-nums;
  color: var(--gold-bright);
}

/* ── Responsive ─────────────────────────────────────────── */
@media (max-width: 980px) {
  .select-copy {
    width: min(420px, 52vw);
  }
  .select-copy h1 {
    font-size: clamp(48px, 6vw, 70px);
  }
  .destination-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .member-grid {
    grid-template-columns: 1fr;
  }
  .sig-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .split {
    grid-template-columns: 1fr;
  }
  .panel-head {
    padding: 30px 34px 20px;
  }
  .panel-body {
    padding: 24px 34px 40px;
  }
}

@media (max-width: 760px) {
  .select-screen {
    padding: calc(16px + var(--safe-top)) calc(17px + var(--safe-right)) calc(14px + var(--safe-bottom)) calc(17px + var(--safe-left));
    background:
      linear-gradient(180deg, rgba(4, 10, 12, 0.55) 0%, rgba(4, 10, 12, 0.1) 25%, rgba(4, 10, 12, 0.72) 62%, rgba(4, 10, 12, 0.95) 100%),
      linear-gradient(90deg, rgba(4, 10, 12, 0.45), transparent 80%);
  }
  .brand-mark {
    width: 38px;
    height: 38px;
    font-size: 20px;
  }
  .brand-words {
    font-size: 10px;
  }
  .select-main {
    align-items: flex-end;
    padding-top: 10px;
  }
  .select-copy {
    width: 100%;
    max-height: 78vh;
  }
  .select-copy h1 {
    margin: 12px 0 10px;
    font-size: clamp(44px, 12.5vw, 60px);
  }
  .select-lede {
    margin-bottom: 16px;
    font-size: 11px;
    line-height: 1.5;
    max-width: 320px;
  }
  .family-picker {
    width: 100%;
    gap: 6px;
  }
  .family-option {
    grid-template-columns: 28px 1fr auto;
    gap: 10px;
    padding: 9px 12px 9px 10px;
  }
  .family-index {
    font-size: 18px;
  }
  .family-option-copy b {
    font-size: 18px;
  }
  .family-option-copy small {
    font-size: 7px;
    margin-top: 2px;
  }
  .family-money b {
    font-size: 10.5px;
  }
  .family-money small {
    font-size: 6px;
  }
  .select-actions {
    margin-top: 13px;
  }
  .select-actions .btn {
    height: 48px;
    flex: 1;
    min-width: 0;
  }
  .preview-label {
    display: none;
  }
  .select-footer {
    display: none;
  }
  .topbar {
    top: calc(9px + var(--safe-top));
    padding: 0 calc(10px + var(--safe-right)) 0 calc(10px + var(--safe-left));
    grid-template-columns: auto 1fr auto;
    gap: 7px;
  }
  .house-pill {
    height: 48px;
    padding: 0 11px 0 6px;
    gap: 8px;
  }
  .crest {
    width: 34px;
    height: 34px;
    font-size: 18px;
  }
  .house-pill-copy b {
    font-size: 9.5px;
    max-width: 92px;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }
  .house-pill-copy small {
    font-size: 6px;
    letter-spacing: 0.12em;
  }
  .chev {
    display: none;
  }
  .day-chip {
    height: 34px;
    padding: 0 9px;
    gap: 7px;
  }
  .day-dot {
    width: 5px;
    height: 5px;
    box-shadow: 0 0 0 3px rgba(216, 178, 116, 0.1);
  }
  .day-copy b {
    font-size: 7px;
    letter-spacing: 0.1em;
  }
  .day-copy small {
    display: none;
  }
  .wealth-pill {
    height: 48px;
    padding: 0 6px 0 9px;
    gap: 6px;
    border-radius: 12px;
  }
  .wealth-copy small {
    font-size: 5.5px;
    letter-spacing: 0.12em;
  }
  .wealth-copy b {
    font-size: 12.5px;
    letter-spacing: -0.04em;
  }
  .income-chip {
    display: none;
  }
  .tutorial {
    top: calc(67px + var(--safe-top));
    font-size: 7px;
    padding: 7px 10px;
    max-width: calc(100vw - 24px);
    white-space: normal;
    text-align: center;
    line-height: 1.4;
  }
  .estate-card {
    display: none;
  }
  .next-day-btn {
    right: calc(12px + var(--safe-right));
    bottom: calc(91px + var(--safe-bottom));
    height: 40px;
    padding: 0 13px 0 6px;
    gap: 7px;
  }
  .next-day-icon {
    width: 27px;
    height: 27px;
    font-size: 13px;
  }
  .next-day-btn b {
    font-size: 8px;
  }
  .next-day-btn small {
    font-size: 6.2px;
  }
  .dock {
    bottom: calc(9px + var(--safe-bottom));
    width: calc(100% - 20px - var(--safe-left) - var(--safe-right));
    max-width: 470px;
    height: 58px;
    border-radius: 16px;
    padding: 5px;
    justify-content: space-between;
  }
  .dock-item {
    flex: 1;
    min-width: 0;
    height: 48px;
    padding: 3px 2px;
