    height: 17px;
  }
  .panel-sheet {
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    width: 100%;
    border-radius: 0;
    border: 0;
  }
  .panel-head {
    padding: calc(22px + var(--safe-top)) 20px 16px;
  }
  .panel-head h2 {
    font-size: 38px;
  }
  .panel-head p {
    font-size: 9px;
  }
  .panel-body {
    padding: 20px 20px calc(34px + var(--safe-bottom));
  }
  .stat-big-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .asset-grid {
    grid-template-columns: 1fr;
  }
  .split-even {
    grid-template-columns: 1fr;
  }
  .sig-grid {
    grid-template-columns: 1fr 1fr;
  }
  .destination-grid {
    grid-template-columns: 1fr 1fr;
    gap: 8px;
  }
  .destination-card {
    min-height: 118px;
    padding: 11px;
  }
  .dest-content {
    height: 92px;
  }
  .dest-content b {
    font-size: 21px;
  }
  .dest-art {
    width: 72px;
    height: 60px;
  }
  .dest-price {
    font-size: 6.3px;
  }
  .dest-price b {
    font-size: 8px;
  }
  .travel-intro {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }
  .dd-head {
