    align-items: stretch;
  }
  .booking-bar .btn {
    width: 100%;
  }
  .ledger-hero {
    flex-direction: column;
    align-items: flex-start;
  }
  .ledger-hero-right {
    text-align: left;
  }
  .switch-household {
    flex-direction: column;
    align-items: flex-start;
  }
  .switch-household .btn {
    width: 100%;
