64:   const g = new THREE.Group();
65:   const accent = new THREE.Color(family.accent);
66:   const bodyMat = new THREE.MeshPhysicalMaterial({
67:     color: family.id === 'average' ? 0xf1f3f3 : 0xf6f1e8,
68:     roughness: 0.23,
69:     metalness: 0.38,
70:     clearcoat: 0.85,
71:   });
72:   const accentMat = new THREE.MeshPhysicalMaterial({
73:     color: accent,
74:     roughness: 0.28,
75:     metalness: 0.5,
76:     clearcoat: 0.5,
77:   });
78:   const dark = std(0x22272a, 0.4, 0.4);
79:   const glass = new THREE.MeshPhysicalMaterial({
80:     color: 0x253b46,
81:     metalness: 0.75,
82:     roughness: 0.02,
83:     transparent: true,
84:     opacity: 0.88,
85:   });
86:   // fuselage
87:   const fuse = new THREE.Mesh(new THREE.CylinderGeometry(0.72, 0.62, 12.5, 24), bodyMat);
88:   fuse.rotation.x = Math.PI / 2;
89:   fuse.castShadow = true;
90:   g.add(fuse);
91:   const nose = sph(0.72, bodyMat, 0, 0, 6.45, 20);
92:   nose.scale.set(1, 1, 1.55);
93:   g.add(nose);
94:   const tailCone = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.62, 2.0, 18), bodyMat);
95:   tailCone.rotation.x = Math.PI / 2;
96:   tailCone.position.set(0, 0.1, -7.0);
97:   g.add(tailCone);
98:   // stripe
99:   const stripe = new THREE.Mesh(new THREE.CylinderGeometry(0.725, 0.725, 0.22, 24, 1, true, -0.6, 1.2), accentMat);
100:   stripe.rotation.x = Math.PI / 2;
101:   stripe.position.z = 0.2;
102:   stripe.scale.z = 12.4;
103:   g.add(stripe);
104:   // windows
105:   for (let i = 0; i < 8; i++) {
106:     [-1, 1].forEach((side) => {
107:       const w = box(0.05, 0.2, 0.28, glass, side * 0.69, 0.25, -3.4 + i * 0.85);
108:       g.add(w);
109:     });
110:   }
111:   // cockpit
112:   const cockpit = sph(0.55, glass, 0, 0.3, 5.9, 16);
113:   cockpit.scale.set(1.1, 0.7, 1.1);
114:   g.add(cockpit);
115:   // wings
116:   const wingShape = new THREE.Shape();
117:   wingShape.moveTo(-0.9, 0);
118:   wingShape.lineTo(8.3, -1.15);
119:   wingShape.lineTo(8.5, 0.3);
120:   wingShape.lineTo(1.2, 1.5);
121:   wingShape.closePath();
122:   const wingGeo = new THREE.ExtrudeGeometry(wingShape, { depth: 0.12, bevelEnabled: false });
123:   [-1, 1].forEach((side) => {
124:     const wing = new THREE.Mesh(wingGeo, bodyMat);
125:     wing.rotation.x = -Math.PI / 2;
126:     wing.rotation.z = side < 0 ? Math.PI : 0;
127:     wing.position.set(0, -0.05, 0.4);
128:     wing.scale.x = side;
129:     wing.castShadow = true;
130:     g.add(wing);
131:     const tip = box(0.25, 0.22, 1.4, accentMat, side * 8.4, 0, 0.1);
132:     g.add(tip);
133:     const engine = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.4, 1.3, 16), bodyMat);
134:     engine.rotation.x = Math.PI / 2;
135:     engine.position.set(side * 3.4, -0.35, 1.7);
136:     engine.castShadow = true;
137:     g.add(engine);
138:     const intake = new THREE.Mesh(new THREE.CylinderGeometry(0.26, 0.3, 0.06, 16), dark);
139:     intake.rotation.x = Math.PI / 2;
140:     intake.position.set(side * 3.4, -0.35, 2.37);
141:     g.add(intake);
142:   });
143:   // tail
144:   const finShape = new THREE.Shape();
145:   finShape.moveTo(0, 0);
146:   finShape.lineTo(0, 2.5);
147:   finShape.lineTo(2.0, 0.28);
148:   finShape.lineTo(2.0, 0);
149:   finShape.closePath();
150:   const finGeo = new THREE.ExtrudeGeometry(finShape, { depth: 0.14, bevelEnabled: false });
151:   const fin = new THREE.Mesh(finGeo, bodyMat);
152:   fin.position.set(0, 0.2, -7.0);
153:   fin.rotation.y = Math.PI / 2;
154:   fin.castShadow = true;
155:   g.add(fin);
156:   const finAccent = box(0.16, 1.9, 0.1, accentMat, 0, 1.45, -7.1);
157:   finAccent.rotation.z = -0.18;
158:   g.add(finAccent);
159:   const stab = box(5.3, 0.13, 1.0, bodyMat, 0, 0.1, -6.85);
160:   g.add(stab);
161:   // belly light
162:   const light = new THREE.PointLight(0xffe0ad, 1.0, 12, 2);
163:   light.position.set(0, -0.4, 4.2);
164:   g.add(light);
165:   g.userData = { light };
166:   return g;
167: }
