191: export function buildFlightWorld(family, destination) {
192:   const root = new THREE.Group();
193:   root.name = 'flight-world';
194:   const clouds = new THREE.Group();
195:   root.add(clouds);
196:   const material = new THREE.MeshBasicMaterial({ color: 0xffe8d5, transparent: true, opacity: 0.5, depthWrite: false });
197:   for (let i = 0; i < 46; i++) {
198:     const x = (Math.random() - 0.5) * 75;
199:     const y = -5 + Math.random() * 7;
200:     const z = -55 + Math.random() * 75;
201:     const s = 2.7 + Math.random() * 6.5;
202:     const cl = cloud(clouds, x, y, z, s, 0.22 + Math.random() * 0.3);
203:     cl.rotation.y = Math.random() * TAU;
204:     cl.userData.speed = 0.4 + Math.random() * 0.8;
205:   }
206:   // low cloud sea
207:   const sea = new THREE.Mesh(
208:     new THREE.PlaneGeometry(250, 250, 1, 1),
209:     new THREE.MeshBasicMaterial({ color: 0xf5d9c6, transparent: true, opacity: 0.2, depthWrite: false })
210:   );
211:   sea.rotation.x = -Math.PI / 2;
212:   sea.position.y = -7;
213:   root.add(sea);
214: 
215:   const plane = buildPlane(family);
216:   plane.position.set(0, 2.8, 0);
217:   plane.rotation.y = 0.0;
218:   plane.rotation.z = 0.045;
219:   root.add(plane);
220: 
221:   return {
222:     root,
223:     kind: 'flight',
224:     destination,
225:     family,
226:     anim: {
227:       plane,
228:       clouds,
229:       time: 0,
230:       update(time, dt) {
231:         this.time += dt;
232:         plane.position.y = 2.8 + Math.sin(time * 0.9) * 0.12;
233:         plane.rotation.z = 0.045 + Math.sin(time * 0.7) * 0.025;
234:         clouds.children.forEach((cl) => {
235:           cl.position.z += dt * cl.userData.speed * 2.2;
236:           if (cl.position.z > 45) cl.position.z = -70;
237:         });
238:       },
239:     },
240:   };
241: }
