288: function eiffel(parent, x, z, scale = 1) {
289:   const g = new THREE.Group();
290:   const mat = std(0x6c5a47, 0.6, 0.35);
291:   const warm = std(0xc59754, 0.5, 0.4, { emissive: 0xb67a30, emissiveIntensity: 0.15 });
292:   const levels = [
293:     { y: 0.15, spread: 3.25, h: 0.25 },
294:     { y: 2.1, spread: 2.25, h: 0.3 },
295:     { y: 5.5, spread: 1.3, h: 0.28 },
296:     { y: 8.7, spread: 0.55, h: 0.22 },
297:   ];
298:   // four legs, angled inward at tiers
299:   [[-1, -1], [-1, 1], [1, -1], [1, 1]].forEach(([sx, sz]) => {
300:     for (let i = 0; i < 3; i++) {
301:       const lower = levels[i];
302:       const upper = levels[i + 1];
303:       const a = new THREE.Vector3(sx * lower.spread, lower.y, sz * lower.spread);
304:       const b = new THREE.Vector3(sx * upper.spread, upper.y, sz * upper.spread);
305:       const dir = b.clone().sub(a);
306:       const len = dir.length();
307:       const leg = cyl(0.1, 0.13, len, 8, i === 2 ? warm : mat, (a.x + b.x) / 2, (a.y + b.y) / 2, (a.z + b.z) / 2);
308:       leg.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
309:       g.add(leg);
310:     }
311:   });
312:   levels.forEach((l) => {
313:     const ring = new THREE.Mesh(new THREE.TorusGeometry(l.spread, 0.08, 6, 22), warm);
314:     ring.rotation.x = Math.PI / 2;
315:     ring.position.y = l.y;
316:     g.add(ring);
317:     g.add(box(l.spread * 2.1, l.h, 0.22, warm, 0, l.y + 0.1, 0));
318:     g.add(box(0.22, l.h, l.spread * 2.1, warm, 0, l.y + 0.1, 0));
319:   });
320:   // deck boxes
321:   g.add(box(4.8, 0.32, 4.8, warm, 0, 0.42, 0));
322:   g.add(box(3.2, 0.25, 3.2, warm, 0, 2.35, 0));
323:   g.add(cyl(0.1, 0.24, 4.2, 8, warm, 0, 11.0, 0));
324:   g.add(cyl(0.04, 0.06, 2.4, 6, warm, 0, 14.2, 0));
325:   g.add(sph(0.11, std(0xffd58c, 0.2, 0.1, { emissive: 0xffae44, emissiveIntensity: 2 }), 0, 15.4, 0, 8));
326:   g.position.set(x, -0.3, z);
327:   g.scale.setScalar(scale);
328:   parent.add(g);
329:   return g;
330: }
